A={'X-Actor':'alice'}
B={'X-Actor':'carol'}
R={'X-Actor':'reader'}
def request(method, path, body=None, who=A, **kw):
    if body is not None: kw['json']=body
    return C.request(method,path,headers=who,**kw)
def ok(response, statuses=(200,201)):
    assert response.status_code in statuses, (response.status_code,response.text)
    return response.json()
def denied(response):
    assert response.status_code in (400,401,403,404,409,412,413,422,428,429), (response.status_code,response.text)
def envelope(response):
    denied(response)
    value=response.json().get('error')
    assert isinstance(value,dict) and isinstance(value.get('code'),str) and isinstance(value.get('message'),str)
def envelopes(responses):
    refused=[r for r in responses if r.status_code>=400]
    assert refused, 'no refused request to inspect'
    for response in refused: envelope(response)

for key in ['a','b']: ok(request('POST','/jobs',{'id':key,'label':key}))
def create(jobs=None,key='r',who=A): return request('POST','/runs',{'id':key,'jobs':jobs if jobs is not None else ['a','b']},who)
def act(action,who=A): return request('POST','/runs/r/'+action,who=who)
def job(key): return ok(request('GET','/jobs/'+key))
def finish(key):
    ok(request('POST','/jobs/'+key+'/dispatch'))
    ok(request('POST','/jobs/'+key+'/complete',{'result':'ok'}))

r=ok(create()); assert r['state']=='draft' and r['done']==0 and job('a')['state']=='queued'

