from foundation import STORE
from copy import deepcopy
import json
from collections import Counter
def new_events(before,after):
    old=Counter(json.dumps(e,sort_keys=True) for e in before)
    current=Counter(json.dumps(e,sort_keys=True) for e in after)
    return [json.loads(e) for e,n in (current-old).items() for _ in range(n)]
who={'name':'alice','tenant':'north','role':'editor'}
before=deepcopy([e for e in STORE.events if e['tenant']=='north' and e['entity']=='bookings' and e['id']=='b'])
ok(delete())
after=deepcopy([e for e in STORE.events if e['tenant']=='north' and e['entity']=='bookings' and e['id']=='b'])
assert len(after)>len(before), 'deletion missing from reservation audit'
assert any(e['actor']=='alice' and e['tenant']=='north' and e['id']=='b' for e in new_events(before,after))
before=after
ok(restore())
after=deepcopy([e for e in STORE.events if e['tenant']=='north' and e['entity']=='bookings' and e['id']=='b'])
assert len(after)>len(before), 'restoration missing from reservation audit'
assert any(e['actor']=='alice' and e['tenant']=='north' and e['id']=='b' for e in new_events(before,after))

